  if (typeof prefix !== 'string' || prefix.length === 0) {
    throw new TypeError('prefix must be a non-empty string');
  }
  if (!Number.isInteger(count) || count < 1) {
    throw new TypeError('count must be a positive integer');
  }

  const file = stateFile();
  await acquireLock(lockDir(), staleMs());
  try {
    const state = await readState(file);
    state.counters ??= {};
    const prev = Number.isInteger(state.counters[prefix]) ? state.counters[prefix] : 0;
    const start = prev + 1;
    const end = prev + count;
    state.counters[prefix] = end;
    await writeStateAtomic(file, state);
    return { prefix, start, end };
  } finally {
    await releaseLock(lockDir());
  }
}

async function readState(file) {
  try {
    return JSON.parse(await readFile(file, 'utf8'));
  } catch (err) {
    if (err.code === 'ENOENT') return {};
    throw err;
  }
}

/** Write-then-rename so readers never observe a torn state file. */
async function writeStateAtomic(file, state) {
  await mkdir(dirname(file), { recursive: true });
  const tmp = `${file}.${process.pid}.${randomBytes(4).toString('hex')}.tmp`;
  await writeFile(tmp, JSON.stringify(state, null, 2));
  await rename(tmp, file);
}

async function acquireLock(dir, staleMs) {
  for (let attempt = 0; ; attempt++) {
    try {
      await mkdir(dir); // exclusive creation = acquiring the lock
      return;
    } catch (err) {
      if (err.code !== 'EEXIST') throw err;
    }

    // Lock is held by someone. Take it over if it looks stale (crashed holder).
    try {
      const st = await stat(dir);
      if (Date.now() - st.mtimeMs > staleMs) {
        // Brief re-check so we don't delete a lock that was just re-created;
        // only remove if the directory truly hasn't changed underneath us.
        await delay(15);
        const again = await stat(dir).catch(() => null);
        if (!again || again.mtimeMs === st.mtimeMs) {
          await rm(dir, { recursive: true, force: true });
          continue; // immediately retry acquisition
        }
      }
    } catch {
      // vanished while we looked at it — fall through to retry
    }

    // Jittered exponential backoff, capped at ~64 ms.
    await delay(1 + Math.floor(Math.random() * Math.min(2 ** Math.min(attempt, 6), 64)));
  }
}

async function releaseLock(dir) {
  await rm(dir, { recursive: true, force: true });
}
