// Run with: node --test

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, mkdir, readFile, rm, stat, utimes, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = dirname(fileURLToPath(import.meta.url));
const COUNTER_URL = pathToFileURL(join(ROOT, '..', 'counter.mjs')).href;

const { nextRange } = await import(COUNTER_URL);
const { pad7, footer, stampText, stampFile } = await import(
  pathToFileURL(join(ROOT, '..', 'stamp.mjs')).href
);

/**
 * Isolated workspace: fresh temp dir; state/lock paths point into it so
 * tests never touch each other or the repo. Spawns a worker child process
 * that reserves one range and prints it as JSON.
 */
async function withEnv(fn) {
  const dir = await mkdtemp(join(tmpdir(), 'bates-test-'));
  const env = {
    ...process.env,
    COUNTER_STATE_FILE: join(dir, 'state.json'),
    COUNTER_LOCK_DIR: join(dir, 'state.json.lock'),
  };
  try {
    return await fn(dir, env);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

function spawnWorker(env) {
  // Worker script is passed via -e (as ESM) instead of living in test/,
  // so `node --test` doesn't discover it as a test file.
  const code = `
    const { nextRange } = await import(${JSON.stringify(COUNTER_URL)});
    const r = await nextRange(process.env.WORKER_PREFIX, Number(process.env.WORKER_COUNT));
    console.log(JSON.stringify(r));
  `;
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, ['--input-type=module', '-e', code], { env });
    let out = '';
    let err = '';
    child.stdout.on('data', (d) => (out += d));
    child.stderr.on('data', (d) => (err += d));
    child.on('error', reject);
    child.on('close', (code_) => {
      if (code_ !== 0) return reject(new Error(`worker exited ${code_}:\n${err}`));
      try {
        resolve(JSON.parse(out.trim()));
      } catch (e) {
        reject(new Error(`bad worker output ${JSON.stringify(out)}\n${err}`));
      }
    });
  });
}

test('8 concurrent workers x 50 pages: 400 unique, contiguous, gap-free numbers', async () => {
  await withEnv(async (_dir, env) => {
    const PREFIX = 'TEST';
    const results = await Promise.all(
      Array.from({ length: 8 }, () => {
        env.WORKER_PREFIX = PREFIX;
        env.WORKER_COUNT = '50';
        return spawnWorker(env);
      })
    );

    const numbers = [];
    for (const r of results) {
      assert.equal(r.prefix, PREFIX);
      assert.equal(r.start + 50 - 1, r.end, `range size must be 50: ${JSON.stringify(r)}`);
      for (let n = r.start; n <= r.end; n++) numbers.push(n);
    }

    assert.equal(numbers.length, 400, 'exactly 400 numbers issued');
    assert.equal(new Set(numbers).size, 400, 'all numbers unique');

    const sorted = [...numbers].sort((a, b) => a - b);
    sorted.forEach((n, i) => assert.equal(n, i + 1, `expected ${i + 1}, got ${n}`));

    // Persisted counter agrees with the highest issued number.
    const state = JSON.parse(await readFile(env.COUNTER_STATE_FILE, 'utf8'));
    assert.equal(state.counters[PREFIX], 400);

    // Lock is released afterwards.
    await assert.rejects(() => stat(env.COUNTER_LOCK_DIR), { code: 'ENOENT' });
  });
});

test('nextRange advances across sequential calls and validates input', async () => {
  await withEnv(async () => {
    assert.deepEqual(await nextRange('A', 5), { prefix: 'A', start: 1, end: 5 });
    assert.deepEqual(await nextRange('A', 1), { prefix: 'A', start: 6, end: 6 });
    assert.deepEqual(await nextRange('B', 3), { prefix: 'B', start: 1, end: 3 }); // per-prefix counters
    await assert.rejects(() => nextRange('A', 0), TypeError);
    await assert.rejects(() => nextRange('', 1), TypeError);
  });
});

test('padding and footer format (zero-padded to 7)', () => {
  assert.equal(pad7(1), '0000001');
  assert.equal(pad7(42), '0000042');
  assert.equal(pad7(1234567), '1234567');
  assert.equal(footer('ABC', 9), 'ABC-0000009');
});

test('multi-page stamping: every page gets its own footer, \f preserved', async () => {
  await withEnv(async (dir) => {
    const input = join(dir, 'doc.txt');
    await writeFile(input, 'Alpha page\fBeta page\fGamma page');

    const res = await stampFile(input, 'DOC');
    assert.deepEqual(res, { start: 1, end: 3, pages: 3 });

    const out = await readFile(input, 'utf8');
    const pages = out.split('\f');
    assert.equal(pages.length, 3, '\f count preserved');
    assert.match(pages[0], /DOC-0000001\n$/);
    assert.match(pages[1], /DOC-0000002\n$/);
    assert.match(pages[2], /DOC-0000003\n$/);
    assert.match(out, /Alpha page[\s\S]*?DOC-0000001/);

    // Pure helper agrees, including arbitrary start offsets.
    assert.equal(
      stampText('X\fY', 'P', 9999998),
      'X\nP-09999998\n\fY\nP-09999999\n'
    );
  });
});

test('stale lock (old mtime) is taken over without waiting forever', async () => {
  await withEnv(async (_dir, env) => {
    const lock = env.COUNTER_LOCK_DIR;
    await mkdir(lock); // simulate a crashed stamper holding the lock...
    const old = new Date(Date.now() - 60_000); // ...abandoned long ago (> 2 s)
    await utimes(lock, old, old);

    const t0 = Date.now();
    const r = await nextRange('STALE', 3);
    const elapsed = Date.now() - t0;

    assert.ok(elapsed < 1500, `takeover took ${elapsed}ms, should be quick`);
    assert.deepEqual(r, { prefix: 'STALE', start: 1, end: 3 });

    // Counter still works normally after the takeover.
    assert.deepEqual(await nextRange('STALE', 2), { prefix: 'STALE', start: 4, end: 5 });
  });
});
